<script setup lang="ts">const props=defineProps<{locale:'zh'|'en'}>();const input=ref('Hello');const mode=ref<'encode'|'decode'>('encode');const result=computed(()=>{try{if(mode.value==='encode')return btoa(Array.from(new TextEncoder().encode(input.value),x=>String.fromCharCode(x)).join(''));const bytes=Uint8Array.from(atob(input.value),c=>c.charCodeAt(0));return new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{return props.locale==='zh'?'错误：无效的 Base64 或 UTF-8 内容':'Error: invalid Base64 or UTF-8 content'}});const {copied,copy}=useCopy()</script><template><div class="tool-form"><div class="segmented"><button :class="{active:mode==='encode'}" @click="mode='encode'">{{locale==='zh'?'编码':'Encode'}}</button><button :class="{active:mode==='decode'}" @click="mode='decode'">{{locale==='zh'?'解码':'Decode'}}</button></div><label>{{locale==='zh'?'输入文本':'Input text'}}<textarea v-model="input" rows="5" /></label><div class="result-header"><span>OUTPUT</span><button type="button" @click="copy(result)">{{copied?(locale==='zh'?'已复制':'Copied'):(locale==='zh'?'复制':'Copy')}}</button></div><pre class="code-result">{{result}}</pre></div></template>